// Minimal reimplementation of the subset of Python's argparse used by test5.py:
// required options with type=int, --opt value / --opt=value forms, -h/--help,
// and argparse-compatible error/usage output (exit code 2 on error).
import { basename } from 'node:path';

function pythonInt(text) {
  // Mirrors Python's int(str): optional surrounding whitespace, optional sign,
  // digits with single underscores allowed between digits.
  const m = /^\s*([+-]?)([0-9](?:_?[0-9])*)\s*$/.exec(text);
  if (!m) return null;
  return parseInt(m[1] + m[2].replaceAll('_', ''), 10);
}

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog ?? basename(process.argv[1] ?? 'prog');
    this.options = []; // { flag, metavar, required }
  }

  addArgument(flag, { type = 'string', required = false } = {}) {
    const metavar = flag.replace(/^--/, '').toUpperCase();
    this.options.push({ flag, metavar, type, required });
  }

  usageLine() {
    const parts = this.options.map((o) =>
      o.required ? `${o.flag} ${o.metavar}` : `[${o.flag} ${o.metavar}]`
    );
    return `usage: ${this.prog} [-h]${parts.length ? ' ' + parts.join(' ') : ''}`;
  }

  error(message) {
    process.stderr.write(`${this.usageLine()}\n`);
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  printHelp() {
    let out = `${this.usageLine()}\n\noptions:\n  -h, --help  show this help message and exit\n`;
    for (const o of this.options) out += `  ${o.flag} ${o.metavar}\n`;
    process.stdout.write(out);
  }

  parseArgs(argv = process.argv.slice(2)) {
    const values = {};
    const seen = new Set();
    const extras = [];

    for (let i = 0; i < argv.length; i++) {
      let token = argv[i];
      if (token === '-h' || token === '--help') {
        this.printHelp();
        process.exit(0);
      }

      let inlineValue = null;
      const eq = token.indexOf('=');
      if (token.startsWith('--') && eq !== -1) {
        inlineValue = token.slice(eq + 1);
        token = token.slice(0, eq);
      }

      const opt = this.options.find((o) => o.flag === token);
      if (!opt) {
        extras.push(argv[i]);
        continue;
      }

      let raw;
      if (inlineValue !== null) {
        raw = inlineValue;
      } else if (i + 1 < argv.length) {
        raw = argv[++i];
      } else {
        this.error(`argument ${opt.flag}: expected one argument`);
      }

      if (opt.type === 'int') {
        const n = pythonInt(raw);
        if (n === null) {
          this.error(`argument ${opt.flag}: invalid int value: '${raw}'`);
        }
        values[opt.flag] = n;
      } else {
        values[opt.flag] = raw;
      }
      seen.add(opt.flag);
    }

    // argparse checks required arguments before reporting unrecognized ones.
    const missing = this.options
      .filter((o) => o.required && !seen.has(o.flag))
      .map((o) => o.flag);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

