// Minimal directed-graph container mirroring the networkx.DiGraph behavior
// needed by test5.py: insertion-ordered nodes, adjacency with self-loops
// allowed and parallel edges collapsed (successor sets are unique).
export class DiGraph {
  constructor() {
    this.succ = new Map(); // node -> Set of successor nodes
  }

  addNode(node) {
    if (!this.succ.has(node)) this.succ.set(node, new Set());
  }

  addEdge(u, v) {
    this.addNode(u);
    this.addNode(v);
    this.succ.get(u).add(v);
  }

  addEdgesFrom(edges) {
    for (const [u, v] of edges) this.addEdge(u, v);
  }

  nodes() {
    return this.succ.keys();
  }

  successors(node) {
    return this.succ.get(node) ?? new Set();
  }
}

