// Directed-acyclic-graph predicate, mirroring nx.is_directed_acyclic_graph:
// true iff every node can be removed by repeatedly peeling zero-indegree
// nodes (Kahn's topological sort); leftover nodes mean a cycle exists.
export function isDirectedAcyclicGraph(G) {
  const indegree = new Map();
  for (const node of G.nodes()) indegree.set(node, 0);
  for (const u of G.nodes()) {
    for (const v of G.successors(u)) {
      indegree.set(v, indegree.get(v) + 1);
    }
  }

  const queue = [];
  for (const [node, deg] of indegree) {
    if (deg === 0) queue.push(node);
  }

  let visited = 0;
  while (queue.length > 0) {
    const u = queue.shift();
    visited += 1;
    for (const v of G.successors(u)) {
      const d = indegree.get(v) - 1;
      indegree.set(v, d);
      if (d === 0) queue.push(v);
    }
  }

  return visited === indegree.size;
}

