import { ArgumentParser } from './lib/argparse.mjs';
import { DiGraph } from './lib/digraph.mjs';
import { isDirectedAcyclicGraph } from './lib/dag.mjs';

const parser = new ArgumentParser();
parser.addArgument('--a', { type: 'int', required: true });
parser.addArgument('--b', { type: 'int', required: true });
parser.addArgument('--c', { type: 'int', required: true });
parser.addArgument('--d', { type: 'int', required: true });
parser.addArgument('--e', { type: 'int', required: true });
const args = parser.parseArgs();

const G = new DiGraph();
G.addEdgesFrom([
  [args['--a'], args['--b']],
  [args['--b'], args['--c']],
  [args['--c'], args['--d']],
  [args['--d'], args['--e']],
]);
// Python prints booleans as True/False.
console.log(isDirectedAcyclicGraph(G) ? 'True' : 'False'); // 检查是否为有向无环图

